+const DOMPurify = require('dompurify');
+
+/**
+ * Sanitizer for SVG assets. SVG files that come from a project (e.g. costumes
+ * loaded out of an sb3 file) are untrusted content: they can contain scripts,
+ * event handler attributes, embedded HTML (via foreignObject) or javascript:
+ * URLs which would otherwise run in the page's origin as soon as the SVG is
+ * parsed or inserted into the DOM.
+ */
+
+// Reject any URL-ish attribute value that is not safe to keep. DOMPurify
+// already handles most of these, but be explicit about the SVG-specific
+// xlink:href attribute as well.
+DOMPurify.addHook('afterSanitizeAttributes', node => {
+    for (const attribute of ['href', 'xlink:href']) {
+        if (!node.hasAttribute(attribute)) continue;
+        const value = node.getAttribute(attribute)
+            // eslint-disable-next-line no-control-regex
+            .replace(/[\u0000-\u0020\u00a0\u1680\u180e\u2000-\u2029\u205f\u3000]/g, '')
+            .toLowerCase();
+        // Only allow same-document references (e.g. "#gradient1") and data URIs
+        // for images. Everything else (javascript:, data:text/html, ...) goes.
+        if (!(value.startsWith('#') || value.startsWith('data:image/'))) {
+            node.removeAttribute(attribute);
+        }
+    }
+});
+
+/**
+ * Sanitize an SVG string.
+ * @param {!string} svgString The SVG markup to sanitize.
+ * @returns {string} The sanitized SVG markup.
+ */
+const sanitizeSvgString = function (svgString) {
+    return DOMPurify.sanitize(svgString, {
+        USE_PROFILES: {svg: true, svgFilters: true},
+        // Never allow scripting or embedded (X)HTML content.
+        FORBID_TAGS: ['script', 'foreignObject', 'a', 'set', 'animate', 'handler', 'listener'],
+        FORBID_ATTR: ['href', 'xlink:href'],
+        ALLOW_DATA_ATTR: false
+    });
+};
+
+/**
+ * Sanitize the contents of an SVG asset.
+ * @param {!Uint8Array} data The raw bytes of the SVG asset.
+ * @returns {Uint8Array} The sanitized bytes of the SVG asset.
+ */
+const sanitizeByteStream = function (data) {
+    const svgString = new TextDecoder().decode(data);
+    return new TextEncoder().encode(sanitizeSvgString(svgString));
+};
+
+module.exports = {
+    sanitizeSvgString,
+    sanitizeByteStream
+};
