+        .stream()
+        .anyMatch(registeredEndpoint -> isSameService(registeredEndpoint, providedUri));
+  }
+
+  private List<String> getRegisteredExtensionsServices() {
+    return SpServiceDiscovery
+        .getServiceDiscovery()
+        .getServiceEndpoints(DefaultSpServiceGroups.EXT, false, Collections.emptyList());
+  }
