+var DEFAULT_PORT_RE = /:(?:80|443)$/;
+
+function getHost(uri) {
+  if (!uri || typeof uri !== 'string') {
+    return '';
+  }
+  var index = uri.indexOf('://');
+  if (index !== -1) {
+    uri = uri.substring(index + 3);
+  }
+  uri = uri.replace(/[/?#].*$/, '');
+  index = uri.indexOf('@');
+  if (index !== -1) {
+    uri = uri.substring(index + 1);
+  }
+  return uri.replace(DEFAULT_PORT_RE, '').toLowerCase();
+}
+
+function isCrossSite(headers) {
+  var site = headers['sec-fetch-site'];
+  // 支持 Fetch Metadata 的浏览器：只允许同源请求及用户主动访问
+  if (site && site !== 'same-origin' && site !== 'none') {
+    return true;
+  }
+  var origin = headers.origin;
+  if (origin === 'null') {
+    // 来自沙箱页面等不可信来源
+    return true;
+  }
+  var from = getHost(origin) || getHost(headers.referer);
+  if (!from) {
+    // 命令行工具、插件等非浏览器请求不会带 origin 及 referer
+    return false;
+  }
+  return from !== getHost(headers.host);
+}
+
+module.exports = function(req, res, next) {
+  var path = req.path || req.url || '';
+  if (!CGI_RE.test(path) || !isCrossSite(req.headers)) {
+    return next();
+  }
